import { test } from "@e2e/fixtures";
import * as flows from "@e2e/flows";
import * as ui from "@e2e/ui-actions";
import { MANTLE_BASE_URL } from "@e2e/config";

// Skill-mode UI only exists on the Mantle agent (:5006). Skill routing is
// LLM-driven, so we pin catalog display names via `activateSkillMode`.
const WELCOME_SKILL = "Session Start";
const ENTRY_SKILL = "Card Replace";
const ACTIVE_SKILL = "Card Disambiguation";
// Explicit replacement intent routes more reliably than a bare "lost card" note.
const CARD_REPLACE_MESSAGE = "I need to replace my lost credit card";
// Picking a card keeps Card Disambiguation active through action_fetch_accounts tool
// writes (used by the tool-call expand test). A generic replacement yes/no often
// auto-selects a card and hands off to Card Replace, which flakes the skill header.
const CARD_PICK_MESSAGE = "Summit Rewards 6338";
const CARD_CONFIRM_MESSAGE = "yes, the Summit Rewards card";

test.describe("Mantle conversation log", () => {
  test.use({ baseURL: MANTLE_BASE_URL });
  // LLM-driven skill activation and multi-turn routing need more than the 1-min default.
  test.describe.configure({ timeout: 120_000 });

  test("Sub-skill routing surfaces in the conversation log and the history timeline", async ({
    inspectorPage,
  }) => {
    await flows.mantle.activateCardDisambiguationRouting(inspectorPage, {
      expectedWelcomeSkill: WELCOME_SKILL,
      replaceMessage: CARD_REPLACE_MESSAGE,
      recoveryPickMessage: CARD_PICK_MESSAGE,
    });

    await test.step("Assert the log records the entry skill and the sub-skill it calls activating", async () => {
      await ui.conversationLog
        .assertions(inspectorPage)
        .lifecycleRowIsVisible(`${ENTRY_SKILL} skill activated`);
      await ui.conversationLog
        .assertions(inspectorPage)
        .lifecycleRowIsVisible(`${ACTIVE_SKILL} skill activated`);
    });

    await test.step("Assert the history timeline lists both the caller and the called skill", async () => {
      await ui.viewMenu.actions(inspectorPage).switchToHistory();
      await ui.historyTimeline.assertions(inspectorPage).itemIsVisible("Card replace");
      await ui.historyTimeline.assertions(inspectorPage).itemIsVisible("Card disambiguation");
    });
  });

  test("A tool-call group stays expanded across a live tracker update", async ({
    inspectorPage,
  }) => {
    await flows.mantle.activateCardDisambiguationRouting(inspectorPage, {
      expectedWelcomeSkill: WELCOME_SKILL,
      replaceMessage: CARD_REPLACE_MESSAGE,
      recoveryPickMessage: CARD_PICK_MESSAGE,
    });

    await test.step("Elicit a tool call whose memory writes collapse under a toggle", async () => {
      await ui.conversationLog
        .actions(inspectorPage)
        .completeTurn(() =>
          ui.inspectorShell.actions(inspectorPage).sendMessage(CARD_PICK_MESSAGE),
        );
    });

    await test.step("Expand the first tool-call group and assert its nested writes appear", async () => {
      await ui.conversationLog.assertions(inspectorPage).toolCallToggleCountAtLeast(1);
      await ui.conversationLog.actions(inspectorPage).expandFirstToolCall();
      await ui.conversationLog.assertions(inspectorPage).toolCallGroupIsVisible();
    });

    await test.step("Send another message and assert the group survives the live update", async () => {
      // A real socket tracker frame (not a prop re-render) — this is the case the
      // ConversationSession Vitest rerender test cannot prove (remount would drop
      // the expand state keyed on the call id).
      await ui.conversationLog
        .actions(inspectorPage)
        .completeTurn(() =>
          ui.inspectorShell.actions(inspectorPage).sendMessage(CARD_CONFIRM_MESSAGE),
        );
      await ui.conversationLog.assertions(inspectorPage).toolCallGroupIsVisible();
    });
  });
});
